import { z } from 'zod'

/* ---------- API responses. Alerts are generated by the server from the real records; severity is mapped there. ---------- */
export const SEVERITIES = ['critical', 'warning', 'info'] as const
export type AlertSeverity = (typeof SEVERITIES)[number]
export const ALERT_STATUSES = ['unread', 'read', 'acknowledged', 'resolved'] as const
export type AlertStatus = (typeof ALERT_STATUSES)[number]

export const alertSchema = z.object({
  id: z.string(),
  alert_key: z.string(),
  kind: z.string(),
  type_label: z.string(),
  module: z.string(),
  title: z.string(),
  detail: z.string(),
  record_id: z.string().nullable(),
  branch_id: z.string().nullable(),
  branch_name: z.string().nullable(),
  alert_date: z.string(),
  due_date: z.string().nullable(),
  severity: z.enum(SEVERITIES),
  status: z.enum(ALERT_STATUSES),
  href: z.string(),
  first_seen_at: z.string(),
  last_seen_at: z.string(),
  read_at: z.string().nullable(),
  acknowledged_at: z.string().nullable(),
  resolved_at: z.string().nullable(),
})
export type Alert = z.infer<typeof alertSchema>

export const alertPageSchema = z.object({
  items: z.array(alertSchema),
  total: z.number(),
  page: z.number(),
  page_size: z.number(),
})

export const alertSummarySchema = z.object({
  total_active: z.number(),
  critical: z.number(),
  warning: z.number(),
  info: z.number(),
  unread: z.number(),
  acknowledged: z.number(),
  recent: z.array(alertSchema),
  by_module: z.record(z.string(), z.number()),
})
export type AlertSummary = z.infer<typeof alertSummarySchema>

export const unreadCountSchema = z.object({ unread: z.number(), total_active: z.number() })
export const alertFacetsSchema = z.object({
  kinds: z.array(z.tuple([z.string(), z.string()])),
  modules: z.array(z.tuple([z.string(), z.string()])),
})
export type AlertFacets = z.infer<typeof alertFacetsSchema>
